test('a version-only package.json bump is docs; any other package.json edit stays code', () => {
  // base commit must hold package.json at version 1.0.0
  const stamp = run(repo({ 'package.json': '{
  "version": "1.0.1"
}
' }), ['--json']);
  expect(JSON.parse(stamp.stdout)).toMatchObject({ class: 'docs', stamp_only: ['package.json'] });
  const dep = run(repo({ 'package.json': '{
  "version": "1.0.1",
  "dependencies": { "x": "1" }
}
' }), ['--json']);
  expect(JSON.parse(dep.stdout).class).not.toBe('docs');
});

