test('without --gate-tagged, a failing gate scan fails closed to gate', () => {
  const r = repo({ 'src/a.ts': 'export const a = 1;\n' });
  const out = spawnSync(BIN, ['--base', 'main', '--json'], { cwd: r.dir, encoding: 'utf8', timeout: 60_000, env: { ...process.env, GSTACK_STATE_ROOT: r.state } });
  const plan = JSON.parse(out.stdout);
  if (plan.gate_tagged === null) expect(plan.class).toBe('gate');
});

